function execute($sql){
 // $sql = ""SELECT * from investments limit 20"";
$result = $this->conn->query($sql);

$rows = []; 

if ($result->num_rows > 0) {
  // output data of each row
  while($row = $result->fetch_assoc()) { 
    $rows[] = $row;
  }
} else {
  echo ""0 results"";
}
return $rows;
}

